INSERT INTO "Question" VALUES('cmuh9bwni031medanrscee7sk','cmuh9bwng031eedan99necyqv',NULL,'MULTIPLE_CHOICE','Label: "Her smile was like sunrise."','["Simile (like) — compares smile to sunrise, suggesting warmth/hope.","There is not enough information — so invent facts not in the lesson.","Drop all Language Arts vocabulary and pick the longest choice.","Ignore definitions and choose a slogan that sounds related."]',0,'Correct response: Simile (like) — compares smile to sunrise, suggesting warmth/hope.',1,4);
