INSERT INTO "Question" VALUES('cmuh9bx2t04o7edana3viotfu','cmuh9bx2r04nzedanitv0em5i',NULL,'MULTIPLE_CHOICE','In your own words, what does someone need to understand to succeed at “Comparing Texts on the Same Topic”?','["Examples: skipping definitions, unlabeled work, unsupported claims, or not checking.","Do the opposite of the worked example without checking.","Reverse the relationship taught in the worked example.","A clear paraphrase of the skill/definition — not only repeating the title."]',3,'Correct response: A clear paraphrase of the skill/definition — not only repeating the title.',1,4);
