INSERT INTO "Question" VALUES('cmuh9bx3504pnedanhi0wm4yx','cmuh9bx3404pjedanaeuf14fw',NULL,'MULTIPLE_CHOICE','Which statement correctly captures a second core idea students must use for “Media Literacy: Fact vs. Opinion”?','["Skip vocabulary and guess from the answer choices alone.","For reading/English: answer from the passage/rules, not outside stories. For math: translate → represent → solve → check.","Use an answer that fits a different lesson title entirely.","Treat a counterexample as if it were the main rule."]',1,'For reading/English: answer from the passage/rules, not outside stories. For math: translate → represent → solve → check.',1,2);
