INSERT INTO "Question" VALUES('cmuh9bxcg05riedan79oibjny','cmuh9bxce05raedang1rtiweq',NULL,'MULTIPLE_CHOICE','Why skip and return on a time-trap item?','["Protect easier points and return with remaining time.","Item type, mistake cause, correct reasoning, and a follow-up drill tag.","There is not enough information — so invent facts not in the lesson.","Drop all Language Arts vocabulary and pick the longest choice."]',0,'Correct response: Protect easier points and return with remaining time.',1,4);
INSERT INTO "Question" VALUES('cmuh9bxcg05rkedanj5brmb24','cmuh9bxce05raedang1rtiweq',NULL,'MULTIPLE_CHOICE','What belongs in an error log entry?','["The passage itself — not prior knowledge alone.","Do the opposite of the worked example without checking.","Reverse the relationship taught in the worked example.","Item type, mistake cause, correct reasoning, and a follow-up drill tag."]',3,'Correct response: Item type, mistake cause, correct reasoning, and a follow-up drill tag.',1,5);
