INSERT INTO "Question" VALUES('cmuh9bxfw0628edancye5mbf6','cmuh9bxfu0620edangc2h5fh8',NULL,'MULTIPLE_CHOICE','Define one key term from today’s science focus in your own words.','["Must match the lesson vocabulary (e.g., cell, evaporation, force) with a correct student paraphrase.","Observation = measurable/sensed; inference = conclusion based on evidence.","There is not enough information — so invent facts not in the lesson.","Drop all Science vocabulary and pick the longest choice."]',0,'Correct response: Must match the lesson vocabulary (e.g., cell, evaporation, force) with a correct student paraphrase.',1,4);
INSERT INTO "Question" VALUES('cmuh9bxfw062aedanc6r0nbdk','cmuh9bxfu0620edangc2h5fh8',NULL,'MULTIPLE_CHOICE','Give one observation and one inference related to this topic.','["Question should be answerable with observation or experiment, not only opinion.","Do the opposite of the worked example without checking.","Reverse the relationship taught in the worked example.","Observation = measurable/sensed; inference = conclusion based on evidence."]',3,'Correct response: Observation = measurable/sensed; inference = conclusion based on evidence.',1,5);
